parameters.jsCode:
return [
  {
    json: {
      session_id: $json.session_id,
      message_text: $json.message_text,
      timestamp: $json.timestamp,
      question: $json.message_text, 
    // a própria pergunta do cliente
    },
  },
];

// Pegamos o JSON atual
const json = $json;

// Mensagem original do usuário
const message = json.message_text || '';

// 1) Tenta usar o código vindo das entidades (melhor fonte)
let trackingCode = json.entities?.codigo_rastreio || null;

// 2) Se não tiver nas entidades, tenta achar no texto com regex
if (!trackingCode) {
  // Padrão típico: 2 letras + 9 dígitos + 2 letras (ex: RL2024001234BR)
  const regex = /\b[A-Z]{2}\d{9}[A-Z]{2}\b/gi;
  const match = message.match(regex);
  trackingCode = match ? match[0].toUpperCase() : null;
}

return {
  json: {
    ...json,
    tracking_code: trackingCode,
    has_tracking_code: !!trackingCode,
  },
};

const item = $json; // resposta do HTTP ou do Set de simulação

const status = item.status; // ex: "EM_TRANSITO"
let explicacao;

switch (status) {
  case 'POSTADO':
    explicacao = 'Sua encomenda foi recebida pela RápidoLog e está registrada em nosso sistema. Agora ela será separada e preparada para transporte.';
    break;
  case 'EM_PROCESSAMENTO':
    explicacao = 'Seu pacote está no centro de distribuição de origem sendo separado e preparado para transporte.';
    break;
  case 'EM_TRANSITO':
    explicacao = 'Sua encomenda está viajando entre centros de distribuição, a caminho do destino final.';
    break;
  case 'SAIU_PARA_ENTREGA':
    explicacao = 'Sua encomenda está com o entregador, a caminho do endereço de destino. Fique atento, a entrega deve acontecer hoje.';
    break;
  case 'ENTREGUE':
    explicacao = 'Sua encomenda foi entregue com sucesso!';
    break;
  // ... e assim por diante com base no doc
  default:
    explicacao = 'Recebemos um status que não está mapeado, mas sua encomenda segue em processamento em nossa rede.';
}

return {
  json: {
    ...item,
    explicacao,
  }
};

// 1) Texto cru vindo do OpenAI em message.content / mensagem.conteúdo
const raw =
  ($json.mensagem && ($json.mensagem.conteúdo || $json.mensagem.content)) ||
  ($json.message && $json.message.content) ||
  "{}";

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  parsed = { intent: "outro", entities: {} };
}

// 2) Pega os dados originais do cliente lá do node "Edit Fields"
const original = $node["Edit Fields"].json;

// 3) Monta o objeto final com tudo que vamos usar depois
return [
  {
    json: {
      intent: parsed.intent || "outro",
      entities: parsed.entities || {},
      session_id: original.session_id,
      message_text: original.message_text,
      timestamp: original.timestamp,
    },
  },
];

// 1) Resposta crua do HTTP (Xano)
// Se o HTTP estiver vazio, o $json provavelmente será um array vazio ou um objeto.
// Aqui estou assumindo que o HTTP node devolve um array de registros.
const data = $json;

// 2) Verifica se veio algum dado real da API
const hasData = Array.isArray(data) && data.length > 0;

// 3) Se tiver dados reais, usa o primeiro registro.
//    Como a API está vazia, montamos um mock fixo com base no código de rastreio.
const rastreio = hasData ? data[0] : {
  codigo_rastreio: $json.tracking_code || 'RL2024001234BR',
  status: 'EM_TRANSITO',
  origem: 'Campinas - SP',
  destino: 'Salvador - BA',
  ultima_atualizacao: '2025-11-14T14:22:00Z',
  previsao_entrega: '2025-11-18',
};

// 4) Retorna o objeto de rastreio como saída do node
return {
  json: rastreio,
};

// Gera um ID único simples (você pode usar outro método se quiser)
function gerarId() {
  return 'TCK-' + Date.now();
}

// Monta a estrutura base do ticket
const ticket = {
  ticket_id: gerarId(),
  data_abertura: new Date().toISOString(),
  tipo_problema: null,
  nome: null,
  telefone: null,
  email: null,
  codigo_rastreio: $json.entities?.codigo_rastreio || null,
  descricao: null,
  prioridade: "normal",
  status: "aberto"
};

// Envia para o próximo nó
return [
  {
    json: {
      ticket: ticket,
      etapa: "inicio_ticket",
      mensagem_usuario: $json.message_text
    }
  }
];

// Recebe o JSON retornado pelo modelo no nó anterior
const dados = $json;

// Garantir estrutura mínima
const ticket = {
  ticket_id: dados.ticket_id || `TKT-${Date.now()}`,
  nome: dados.nome?.trim() || "Não informado",
  telefone: dados.telefone || "",
  email: dados.email || null,
  codigo_rastreio: dados.codigo_rastreio || "",
  tipo_problema: dados.tipo_problema || "outro",
  descricao: dados.descricao || "",
  status: "aberto",
  data_abertura: new Date().toISOString()
};

// 💡 Normalizações importantes

// Email vazio vira null
if (!ticket.email || ticket.email.trim() === "") {
  ticket.email = null;
}

// Corrigir tipo_problema
const tiposValidos = ["atraso","extravio","avaria","devolucao","outro"];
if (!tiposValidos.includes(ticket.tipo_problema)) {
  ticket.tipo_problema = "outro";
}

// Garantir formato do código de rastreio
ticket.codigo_rastreio = ticket.codigo_rastreio.toUpperCase();

// Retorno preparado para o Postgres
return [
  { json: ticket }
];

